\"\"\"Minimal standard-library client for private text prompts via Responses API.\"\"\"

from __future__ import annotations

import json
import os
from typing import Any, Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = \"https://api.openai.com/v1/responses\"


class OpenAIError(Exception):
    \"\"\"Raised when a Responses API request fails or returns unusable data.\"\"\"


def _extract_text(response: dict[str, Any]) -> str:
    text_parts = []
    for item in response.get(\"output\", []):
        if not isinstance(item, dict) or item.get(\"type\") "'!= "message":
            continue
        for content in item.get("content", []):
            if isinstance(content, dict) and content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    text_parts.append(text)
    if not text_parts:
        raise OpenAIError("The API response did not contain output text.")
    return "".join(text_parts)


def send_prompt(
    prompt: str,
    model: str,
    *,
    api_key: [REDACTED_SECRET] = None,
    timeout: float = 60.0,
) -> str:
    """Send a text prompt and return the generated text.

    The API key defaults to the OPENAI_API_KEY environment variable. Response
    storage is disabled in the request, and prompt or credential values are
    never logged by this module.
    """
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("prompt must be a non-empty string")
    if not isinstance(model, str) or not model.strip():
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError("Set OPENAI_API_KEY or pass api_key explicitly.")

    payload = json.dumps(
        {"model": model, "input": prompt, "store": False}
    ).encode("utf-8")
    request = Request(
        API_URL,
        data=payload,
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as result:
            response_data = json.loads(result.read().decode("utf-8"))
    except HTTPError as error:
        raise OpenAIError(f"Responses API returned HTTP {error.code}.") from None
    except URLError:
        raise OpenAIError("Could not connect to the Responses API.") from None
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIError("The Responses API returned invalid JSON.") from None

    if not isinstance(response_data, dict):
        raise OpenAIError("The Responses API returned an unexpected response.")
    return _extract_text(response_data)
